css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; overflow: hidden; border-radius: 8px; }
.loader .floor { position: absolute; left: 0; right: 0; bottom: 0; height: 16%; background: linear-gradient(color-mix(in srgb, var(--accent-2) 40%, transparent), color-mix(in srgb, var(--accent-2) 10%, transparent)); }
.loader .cone { position: absolute; left: 50%; top: 12%; width: 44%; height: 82%; margin-left: -22%; transform-origin: 50% 0; clip-path: polygon(42% 0, 58% 0, 100% 100%, 0 100%); }
.loader .cone:nth-of-type(1) { background: linear-gradient(color-mix(in srgb, var(--accent) 72%, transparent), transparent 82%); animation: spot-swing-a calc(var(--loader-speed) * 3) ease-in-out infinite; }
.loader .cone:nth-of-type(2) { background: linear-gradient(color-mix(in srgb, var(--accent-2) 62%, transparent), transparent 82%); animation: spot-swing-b calc(var(--loader-speed) * 3) ease-in-out infinite; }
.loader .lamp { position: absolute; left: 42%; top: 4%; width: 16%; height: 12%; border-radius: 4px 4px 40% 40%; background: linear-gradient(#64748b, #1e293b); box-shadow: 0 3px 10px color-mix(in srgb, var(--accent) 60%, transparent); }
@keyframes spot-swing-a { 0%, 100% { transform: rotate(-32deg); } 50% { transform: rotate(28deg); } }
@keyframes spot-swing-b { 0%, 100% { transform: rotate(30deg); } 50% { transform: rotate(-26deg); } }
